import{_ as t,o as a,c as o,a5 as l}from"./chunks/framework.CsGesDJn.js";const f=JSON.parse('{"title":"Sequence Flow — Update Agency Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-5-update-agency-profile/sequence-flow.md","filePath":"feature/agency-workspace/3-4-5-update-agency-profile/sequence-flow.md"}'),d={name:"feature/agency-workspace/3-4-5-update-agency-profile/sequence-flow.md"};function r(i,e,n,c,s,h){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="sequence-flow-—-update-agency-profile" tabindex="-1">Sequence Flow — Update Agency Profile <a class="header-anchor" href="#sequence-flow-—-update-agency-profile" aria-label="Permalink to &quot;Sequence Flow — Update Agency Profile&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.5). This file lists each actor → action → system step in enough detail to draw the sequence diagram directly. Business explanation lives in <code>spec.md</code>. &gt; &gt; Updated 2026-09-23, matching the system as built today.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Owner</strong></li><li><strong>Client</strong> — the BrandHub web application.</li><li><strong>System</strong> — the BrandHub service.</li><li><strong>Database</strong> — PostgreSQL (<code>agencies</code>).</li></ul><hr><h2 id="flow-a-—-update-the-agency-profile-full-replace" tabindex="-1">Flow A — Update the Agency profile (full replace) <a class="header-anchor" href="#flow-a-—-update-the-agency-profile-full-replace" aria-label="Permalink to &quot;Flow A — Update the Agency profile (full replace)&quot;">​</a></h2><ol><li>Owner → Client: opens the Agency Profile in edit mode; the form loads with every current value (3.4.4).</li><li>Owner: changes the fields that need updating and leaves the rest as they are — every value has to come back in the form, because the save replaces the whole profile instead of patching single fields.</li><li>Client → System: submits the full profile (<code>PUT /api/v1/agencies/{agencyId}</code>).</li><li>System — update: a. Loads the Agency by its identifier — not found → <code>404 AGENCY_NOT_FOUND</code>. b. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. c. Validates the name as mandatory — empty → <code>400 VALIDATION_ERROR</code>. d. Replaces every field of the profile with the submitted values; a value that was not sent is cleared. e. Stores the updated profile.</li><li>System → Client: the updated profile of the Agency.</li><li>Client: shows a confirmation and refreshes the form and the logo preview.</li></ol><h2 id="flow-b-—-change-the-logo-uploaded-separately" tabindex="-1">Flow B — Change the logo (uploaded separately) <a class="header-anchor" href="#flow-b-—-change-the-logo-uploaded-separately" aria-label="Permalink to &quot;Flow B — Change the logo (uploaded separately)&quot;">​</a></h2><ol><li>Owner → Client: picks a new logo file on the edit screen.</li><li>Client → System: submits the file for the Agency (<code>POST /api/v1/agencies/{agencyId}/logo</code>, sent as multipart form data).</li><li>System — change the logo: a. Loads the Agency by its identifier — not found → <code>404 AGENCY_NOT_FOUND</code>. b. Confirms the caller is the Owner of the Agency — otherwise <code>403 NOT_AGENCY_OWNER</code>. c. Stores the file. When the file cannot be read → <code>400 FILE_READ_ERROR</code>, rather than an internal failure. d. Fills in the logo of the Agency with the stored location and refreshes the update timestamp.</li><li>System → Client: the Agency profile carrying the new logo location.</li><li>Client: refreshes the logo preview.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>Error code</th></tr></thead><tbody><tr><td>Update</td><td>Agency does not exist</td><td>404</td><td><code>AGENCY_NOT_FOUND</code></td></tr><tr><td>Update</td><td>Caller is not the Owner</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Update</td><td>Name empty</td><td>400</td><td><code>VALIDATION_ERROR</code></td></tr><tr><td>Logo upload</td><td>Agency does not exist</td><td>404</td><td><code>AGENCY_NOT_FOUND</code></td></tr><tr><td>Logo upload</td><td>Caller is not the Owner</td><td>403</td><td><code>NOT_AGENCY_OWNER</code></td></tr><tr><td>Logo upload</td><td>The file cannot be read</td><td>400</td><td><code>FILE_READ_ERROR</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>No divergence from <code>spec.md</code>. The file-read failure on a logo upload returns <code>400 FILE_READ_ERROR</code> rather than a generic internal error and leaves the stored profile untouched.</li></ul>',14)])])}const u=t(d,[["render",r]]);export{f as __pageData,u as default};
